import React, { useMemo, useState } from 'react';

type ProjectStatus = 'active' | 'paused' | 'exceeded' | 'completed';

interface Project {
  id: string;
  name: string;
  quotaPercent: number;
  status: ProjectStatus;
}

const STATUS_LABEL: Record<ProjectStatus, string> = {
  active: 'Активен',
  paused: 'На паузе',
  exceeded: 'Превышен',
  completed: 'Завершён',
};

const STATUS_COLOR: Record<ProjectStatus, string> = {
  active: 'var(--jx-color-success, var(--jx-color-primary))',
  paused: 'var(--jx-color-warning, var(--jx-color-accent))',
  exceeded: 'var(--jx-color-danger, var(--jx-color-critical))',
  completed: 'var(--jx-color-info, var(--jx-color-muted))',
};

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Атлас-CRM', quotaPercent: 42, status: 'active' },
  { id: 'p2', name: 'Ядро-биллинг', quotaPercent: 97, status: 'exceeded' },
  { id: 'p3', name: 'Мобильный клиент', quotaPercent: 68, status: 'active' },
  { id: 'p4', name: 'Аналитика-Q3', quotaPercent: 100, status: 'completed' },
  { id: 'p5', name: 'Внутренний портал', quotaPercent: 15, status: 'paused' },
  { id: 'p6', name: 'Платёжный шлюз', quotaPercent: 81, status: 'exceeded' },
  { id: 'p7', name: 'Складской учёт', quotaPercent: 30, status: 'active' },
  { id: 'p8', name: 'HR-панель', quotaPercent: 55, status: 'paused' },
  { id: 'p9', name: 'Логистика-2', quotaPercent: 100, status: 'completed' },
  { id: 'p10', name: 'Поддержка клиентов', quotaPercent: 22, status: 'active' },
  { id: 'p11', name: 'Отчёты-финансы', quotaPercent: 74, status: 'paused' },
  { id: 'p12', name: 'API-шлюз', quotaPercent: 90, status: 'exceeded' },
];

const PAGE_SIZE = 5;

function QuotaRing({ percent, color }: { percent: number; color: string }) {
  const size = 40;
  const strokeWidth = 4;
  const radius = (size - strokeWidth) / 2;
  const circumference = 2 * Math.PI * radius;
  const clamped = Math.max(0, Math.min(100, percent));
  const offset = circumference * (1 - clamped / 100);

  return (
    <svg
      className="jx-progress-ring"
      width={size}
      height={size}
      viewBox={`0 0 ${size} ${size}`}
      role="img"
      aria-label={`Заполнение квоты: ${clamped}%`}
    >
      <circle
        cx={size / 2}
        cy={size / 2}
        r={radius}
        fill="none"
        stroke="var(--jx-color-border)"
        strokeWidth={strokeWidth}
      />
      <circle
        cx={size / 2}
        cy={size / 2}
        r={radius}
        fill="none"
        stroke={color}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeDasharray={circumference}
        strokeDashoffset={offset}
        transform={`rotate(-90 ${size / 2} ${size / 2})`}
      />
      <text
        x="50%"
        y="50%"
        textAnchor="middle"
        dominantBaseline="central"
        className="jx-progress-ring__label"
      >
        {clamped}%
      </text>
    </svg>
  );
}

export default function ProjectSpendPanel() {
  const allStatuses = useMemo(
    () => Array.from(new Set(PROJECTS.map((p) => p.status))) as ProjectStatus[],
    []
  );
  const [selectedStatuses, setSelectedStatuses] = useState<Set<ProjectStatus>>(new Set());
  const [page, setPage] = useState(0);

  const toggleStatus = (status: ProjectStatus) => {
    setSelectedStatuses((prev) => {
      const next = new Set(prev);
      if (next.has(status)) {
        next.delete(status);
      } else {
        next.add(status);
      }
      return next;
    });
    setPage(0);
  };

  const resetFilters = () => {
    setSelectedStatuses(new Set());
    setPage(0);
  };

  const filteredProjects = useMemo(() => {
    if (selectedStatuses.size === 0) return PROJECTS;
    return PROJECTS.filter((p) => selectedStatuses.has(p.status));
  }, [selectedStatuses]);

  const pageCount = Math.max(1, Math.ceil(filteredProjects.length / PAGE_SIZE));
  const safePage = Math.min(page, pageCount - 1);
  const pageItems = filteredProjects.slice(
    safePage * PAGE_SIZE,
    safePage * PAGE_SIZE + PAGE_SIZE
  );

  return (
    <div className="jx-panel">
      <div className="jx-panel__header">
        <h2 className="jx-panel__title">Расход по проектам</h2>
      </div>

      <div className="jx-chip-group" role="group" aria-label="Фильтры по статусу">
        {allStatuses.map((status) => {
          const isSelected = selectedStatuses.has(status);
          return (
            <button
              key={status}
              type="button"
              className={
                isSelected ? 'jx-chip jx-chip--selected' : 'jx-chip'
              }
              style={{ borderColor: STATUS_COLOR[status] }}
              aria-pressed={isSelected}
              onClick={() => toggleStatus(status)}
            >
              <span
                className="jx-chip__dot"
                style={{ backgroundColor: STATUS_COLOR[status] }}
              />
              <span className="jx-chip__label">{STATUS_LABEL[status]}</span>
              {isSelected && (
                <span className="jx-chip__remove" aria-hidden="true">
                  ×
                </span>
              )}
            </button>
          );
        })}
      </div>

      {filteredProjects.length === 0 ? (
        <div className="jx-empty-state">
          <p className="jx-empty-state__title">Нет проектов по выбранным фильтрам</p>
          <p className="jx-empty-state__description">
            Попробуйте снять часть фильтров, чтобы увидеть больше проектов.
          </p>
          <button type="button" className="jx-button jx-button--secondary" onClick={resetFilters}>
            Сбросить фильтры
          </button>
        </div>
      ) : (
        <>
          <ul className="jx-list">
            {pageItems.map((project) => (
              <li key={project.id} className="jx-list-item">
                <span className="jx-list-item__title">{project.name}</span>
                <QuotaRing percent={project.quotaPercent} color={STATUS_COLOR[project.status]} />
                <span
                  className="jx-badge"
                  style={{
                    borderColor: STATUS_COLOR[project.status],
                    color: STATUS_COLOR[project.status],
                  }}
                >
                  {STATUS_LABEL[project.status]}
                </span>
              </li>
            ))}
          </ul>

          <div className="jx-pagination">
            <button
              type="button"
              className="jx-button jx-button--ghost"
              onClick={() => setPage((p) => Math.max(0, p - 1))}
              disabled={safePage === 0}
            >
              Назад
            </button>
            <span className="jx-pagination__status">
              Страница {safePage + 1} из {pageCount}
            </span>
            <button
              type="button"
              className="jx-button jx-button--ghost"
              onClick={() => setPage((p) => Math.min(pageCount - 1, p + 1))}
              disabled={safePage >= pageCount - 1}
            >
              Вперёд
            </button>
          </div>
        </>
      )}
    </div>
  );
}

